@startuml
class InsuranceCompany {
  + name : string
  + headOfficeAddress : string
}

class Customer {
  + name : string
  + address : string
  + contactDetails : string
}

class Broker {
  + brokerId : int
  + name : string
  + expertise : string
}

class Policy {
  + policyType : string
  + coverageDetails : string
}

class Contract {
  + contractNumber : string
  + signingDate : date
  + paymentFrequency : string
}

class Offer {
  + offerId : string
  + expiryDate : date
  + status : string
}

class ClaimCase {
  + caseId : string
  + description : string
  + status : string
}

class Estimator {
  + estimatorId : int
  + name : string
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : string
  + findings : string
  + dateCreated : date
}

class CompensationDecision {
  + decisionId : string
  + approvedAmount : float
  + eligibleCosts : string
}

class Invoice {
  + invoiceNumber : string
  + amountDue : float
  + dueDate : date
}

InsuranceCompany "1" -- "0..*" Customer
InsuranceCompany "1" -- "0..*" Broker
Broker "1" -- "0..*" Customer : manages
Customer "1" -- "0..*" Contract
Customer "1" -- "0..*" Offer
Customer "1" -- "0..*" ClaimCase
Contract "1" -- "1" Policy
Contract "1" -- "0..*" Invoice
ClaimCase "1" *-- "1..*" EstimatorReport
Estimator "1" -- "0..*" EstimatorReport : assesses
EstimatorReport "1..*" -- "0..1" CompensationDecision : informs
CompensationDecision "1" -- "1" ClaimCase : resolves
@enduml

